// The storage boundary. Handlers talk to THIS interface; the real S3 adapter will implement it later.
// Today there are two adapters: memory (demo) and local disk (development only). No cloud, no AWS.
//
// Safety rules every adapter must follow:
//  - keys are generated by the server from validated ids - user input (like a filename) never becomes a key,
//  - no method returns or reveals a filesystem path, URL or bucket name,
//  - nothing here deletes a committed original except the one failure path in the upload handler for a file
//    that was written a moment earlier and never got a database record (see `deleteUnreferencedUpload`).

export type StorageKind = "memory" | "local-disk" | "s3";
export interface PrivateStorageMetadata { sizeBytes: number; storageKind: StorageKind; }

export interface MediaStorage {
  readonly kind: StorageKind;
  /** Write bytes to a temporary "staging" key. Fails if the key already exists. */
  stage(stagingKey: string, data: Uint8Array): Promise<void>;
  /**
   * Run `work` with a real file path for the staged bytes (needed by ffprobe).
   * The path is for trusted server code only: never return it to a user or put it in a log or error.
   */
  runWithStagedFile<T>(stagingKey: string, work: (filePath: string) => Promise<T>): Promise<T>;
  /** Move a staged object to its final key. Refuses to overwrite an existing object. */
  commit(stagingKey: string, finalKey: string): Promise<void>;
  /** Remove a staged object (it never became media). Missing is fine. */
  discardStaged(stagingKey: string): Promise<void>;
  exists(key: string): Promise<boolean>;
  /** Size in bytes of a committed object, or null if it does not exist. */
  statSize(key: string): Promise<number | null>;
  /** Private object facts only. Never includes a path, storage key, URL, or bucket name. */
  getPrivateMetadata(key: string): Promise<PrivateStorageMetadata | null>;
  /** Streams a committed object (optionally just bytes start..end inclusive). For server use only: never hand a path or key to a browser. */
  openRead(key: string, range?: { start: number; end: number }): Promise<ReadableStream<Uint8Array>>;
  /**
   * Remove an object that was committed moments ago by a FAILED upload and has no database record.
   * Never call this for media that has a record.
   */
  deleteUnreferencedUpload(finalKey: string): Promise<void>;
  /**
   * Run `work` with a real file path for a committed object. The path stays private:
   * it is never returned to a browser, a log, or an error message.
   */
  runWithCommittedFile<T>(key: string, work: (filePath: string) => Promise<T>): Promise<T>;
  /**
   * Copy a local file the server just created into a new key. Refuses to overwrite.
   * Returns the stored size. The source file is left in place for the caller to delete.
   */
  importLocalFile(finalKey: string, sourcePath: string): Promise<number>;
  /** Copies an existing private object to a fresh key without exposing its storage path. */
  copyCommittedToStaging(sourceKey: string, stagingKey: string, assertLease?: () => void): Promise<number>;
}

export class InvalidStorageKeyError extends Error {
  constructor() { super("Invalid storage key."); this.name = "InvalidStorageKeyError"; } // never echoes the key or any path
}

const SEGMENT = /^[A-Za-z0-9_-]{1,64}$/;

/** Keys look like "media/<userId>/<mediaId>": 1 to 4 plain segments. Everything else (dots, slashes, nulls...) is refused. */
export function parseStorageKey(key: string): string[] {
  if (typeof key !== "string" || key.length === 0 || key.length > 300) throw new InvalidStorageKeyError();
  const segments = key.split("/");
  if (segments.length > 4 || !segments.every((s) => SEGMENT.test(s))) throw new InvalidStorageKeyError();
  return segments;
}

/** Each id must be ONE plain segment. (Checking only the joined key would let an id like "a/b" add an extra path level.) */
function assertSingleSegment(id: string): void { if (typeof id !== "string" || !SEGMENT.test(id)) throw new InvalidStorageKeyError(); }

export const mediaKeyFor = (ownerId: string, mediaId: string): string => { assertSingleSegment(ownerId); assertSingleSegment(mediaId); return `media/${ownerId}/${mediaId}`; };
export const thumbnailKeyFor = (ownerId: string, mediaId: string): string => { assertSingleSegment(ownerId); assertSingleSegment(mediaId); return `thumb/${ownerId}/${mediaId}`; };
export const stagingKeyFor = (mediaId: string): string => { assertSingleSegment(mediaId); return `staging/${mediaId}`; };
export const renderKeyFor = (ownerId: string, exportId: string): string => { assertSingleSegment(ownerId); assertSingleSegment(exportId); return `render/${ownerId}/${exportId}`; };

export interface StorageDescription { label: string; persistent: boolean; warning: string; }

/** Plain words for the UI so nobody mistakes demo memory, local disk and (future) cloud storage for each other. */
export function describeStorage(kind: StorageKind | null): StorageDescription {
  switch (kind) {
    case "memory": return { label: "Demo storage (server memory)", persistent: false, warning: "Uploaded files are kept in server memory and are discarded when the server restarts." };
    case "local-disk": return { label: "Private folder on this computer", persistent: true, warning: "Files are saved in a private folder on this computer. They are not stored in the database. Demo mode still keeps only the file list in memory." };
    case "s3": return { label: "Cloud storage", persistent: true, warning: "Cloud storage is not connected in this build." };
    default: return { label: "Not available", persistent: false, warning: "Uploads are not available: no storage is configured." };
  }
}
